<?php
 namespace Pterodactyl\Services\Dezerx\Staff; use Carbon\CarbonImmutable; use Illuminate\Database\Eloquent\Builder; use Pterodactyl\Exceptions\DisplayException; use Pterodactyl\Models\Dezerx\StaffFeedback; use Pterodactyl\Models\Dezerx\StaffRequest; use Pterodactyl\Models\User; use Pterodactyl\Services\Dezerx\Avatars; class StaffReviews { private const BOARD_LIMIT = 25; private const MONTH_LIMIT = 24; public static function canLeave(StaffRequest $request, ?User $user): bool { $server = $request->server; return $user !== null && $server !== null && (int) $server->owner_id === $user->id && $request->staff_id !== null && $request->started_at !== null && in_array($request->status, StaffRequest::CLOSED_STATUSES, true); } public static function leave(StaffRequest $request, User $user, string $mood, string $note): StaffFeedback { if (!self::canLeave($request, $user)) { throw new DisplayException('There is nothing to say about this session yet.'); } if (!in_array($mood, StaffFeedback::MOODS, true)) { throw new DisplayException('Pick one of the three faces.'); } return StaffFeedback::query()->updateOrCreate( ['request_id' => $request->id], [ 'staff_id' => $request->staff_id, 'user_id' => $user->id, 'mood' => $mood, 'note' => self::clean($note), ] ); } public static function of(StaffRequest $request): ?array { $feedback = $request->feedback; return $feedback === null ? null : [ 'mood' => $feedback->mood, 'note' => (string) ($feedback->note ?? ''), 'at' => $feedback->created_at?->toAtomString(), ]; } public static function board(?string $month = null): array { $window = self::window($month); $sessions = StaffRequest::query() ->whereNotNull('staff_id') ->whereNotNull('started_at') ->when($window !== null, fn (Builder $query) => $query->whereBetween('started_at', $window)) ->groupBy('staff_id') ->selectRaw('staff_id, count(*) as sessions') ->selectRaw('sum(case when status = ? then 1 else 0 end) as resolved', [StaffRequest::RESOLVED]) ->get() ->keyBy('staff_id'); $moods = StaffFeedback::query() ->whereNotNull('staff_id') ->when($window !== null, fn (Builder $query) => $query->whereBetween('created_at', $window)) ->groupBy('staff_id') ->selectRaw('staff_id') ->selectRaw('sum(case when mood = ? then 1 else 0 end) as happy', [StaffFeedback::HAPPY]) ->selectRaw('sum(case when mood = ? then 1 else 0 end) as okay', [StaffFeedback::OKAY]) ->selectRaw('sum(case when mood = ? then 1 else 0 end) as sad', [StaffFeedback::SAD]) ->get() ->keyBy('staff_id'); $ids = $sessions->keys()->merge($moods->keys())->unique()->values(); $people = User::query()->whereIn('id', $ids)->get(['id', 'username', 'email', 'dezerx_preferences'])->keyBy('id'); $rows = $ids ->map(function (int $id) use ($sessions, $moods, $people) { $person = $people->get($id); $mood = $moods->get($id); return [ 'staff' => $person?->username, 'avatar' => Avatars::hash($person), 'avatarUrl' => Avatars::custom($person), 'sessions' => (int) ($sessions->get($id)->sessions ?? 0), 'resolved' => (int) ($sessions->get($id)->resolved ?? 0), 'happy' => (int) ($mood->happy ?? 0), 'okay' => (int) ($mood->okay ?? 0), 'sad' => (int) ($mood->sad ?? 0), ]; }) ->filter(fn (array $row) => $row['staff'] !== null) ->sortByDesc(fn (array $row) => [$row['sessions'], $row['happy']]) ->values() ->take(self::BOARD_LIMIT) ->all(); $summary = self::summary($window); return [ 'board' => $rows, 'summary' => $summary, 'verdict' => self::verdict($summary), 'month' => $window === null ? null : $month, 'months' => self::months(), ]; } private static function window(?string $month): ?array { if ($month === null || preg_match('/^\d{4}-\d{2}$/', $month) !== 1) { return null; } try { $start = CarbonImmutable::createFromFormat('Y-m-d H:i:s', $month . '-01 00:00:00'); } catch (\Throwable) { return null; } return $start === null ? null : [$start, $start->endOfMonth()]; } private static function months(): array { $first = StaffRequest::query()->whereNotNull('started_at')->min('started_at'); if ($first === null) { return []; } $month = CarbonImmutable::parse($first)->startOfMonth(); $now = CarbonImmutable::now()->startOfMonth(); $months = []; while ($month->lessThanOrEqualTo($now) && count($months) < self::MONTH_LIMIT) { $months[] = $month->format('Y-m'); $month = $month->addMonth(); } return array_reverse($months); } private static function summary(?array $window): array { $counts = StaffFeedback::query() ->when($window !== null, fn (Builder $query) => $query->whereBetween('created_at', $window)) ->selectRaw('mood, count(*) as total') ->groupBy('mood') ->pluck('total', 'mood'); return [ 'happy' => (int) ($counts[StaffFeedback::HAPPY] ?? 0), 'okay' => (int) ($counts[StaffFeedback::OKAY] ?? 0), 'sad' => (int) ($counts[StaffFeedback::SAD] ?? 0), ]; } private static function verdict(array $summary): string { $total = $summary['happy'] + $summary['okay'] + $summary['sad']; if ($total < 1) { return 'none'; } $score = ($summary['happy'] + ($summary['okay'] / 2)) / $total; return match (true) { $score >= 0.75 => 'great', $score >= 0.45 => 'okay', default => 'poor', }; } private static function clean(string $note): string { $text = str_replace(["\r\n", "\r"], "\n", trim($note)); $text = preg_replace('/\n{3,}/', "\n\n", $text) ?? ''; $text = preg_replace('/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/u', '', $text) ?? ''; return mb_substr(trim($text), 0, StaffFeedback::MAX_NOTE); } } 